        print("Nothing to do!")
    for i, t in enumerate(todos, 1):
        print(f"{i}. [{'x' if t['done'] else ' '}] {t['title']}")

def main():
    todos = load()
    while True:
        cmd = input("\n(a)dd (d)one (r)emove (l)ist (q)uit > ").lower()
