            todos.append({"title": input("Task: "), "done": False})
        elif cmd == "d":
            show(todos); todos[int(input("Number: ")) - 1]["done"] = True
        elif cmd == "r":
            show(todos); todos.pop(int(input("Number: ")) - 1)
        elif cmd == "l":
            show(todos)
        elif cmd == "q":
            break
        save(todos)

if __name__ == "__main__":
