    // println!("{a}");        // compile error

    let c = b.clone();         // explicit deep copy
    print_len(&c);             // borrow immutably
    println!("{c}");           // still usable

    let mut s = String::from("x");
    append(&mut s);            // borrow mutably
    println!("{s}");
}

fn print_len(s: &String) { println!("{}", s.len()); }
fn append(s: &mut String) { s.push_str("yz"); }
```

The borrow checker enforces these rules at compile time, which prevents data races, dangling pointers, and use-after-free.

