```go
package main

import (
	"encoding/json"
	"net/http"
	"strconv"
	"sync"
)

type Todo struct {
	ID    int    `json:"id"`
	Title string `json:"title"`
	Done  bool   `json:"done"`
}

var (
	mu    sync.Mutex
	todos = map[int]Todo{}
	next  = 1
)

func main() {
	http.HandleFunc("GET /todos", func(w http.ResponseWriter, r *http.Request) {
		mu.Lock(); defer mu.Unlock()
		list := make([]Todo, 0, len(todos))
		for _, t := range todos { list = append(list, t) }
		json.NewEncoder(w).Encode(list)
	})
	http.HandleFunc("POST /todos", func(w http.ResponseWriter, r *http.Request) {
		var t Todo
		if err := json.NewDecoder(r.Body).Decode(&t); err != nil || t.Title == "" {
			http.Error(w, "bad request", 400); return
		}
		mu.Lock(); t.ID = next; next++; todos[t.ID] = t; mu.Unlock()
		w.WriteHeader(201)
		json.NewEncoder(w).Encode(t)
	})
	http.HandleFunc("DELETE /todos/{id}", func(w http.ResponseWriter, r *http.Request) {
		id, _ := strconv.Atoi(r.PathValue("id"))
		mu.Lock(); delete(todos, id); mu.Unlock()
		w.WriteHeader(204)
	})
	http.ListenAndServe(":8080", nil)
}
```

The mutex protects the map from concurrent requests. This needs Go 1.22+ for method and path patterns.
